-- 只會新增，不會刪除或改動既有資料
CREATE TABLE IF NOT EXISTS records (prop TEXT NOT NULL, date TEXT NOT NULL, room TEXT NOT NULL, data TEXT NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY (prop, date, room));
CREATE TABLE IF NOT EXISTS config (prop TEXT PRIMARY KEY, data TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS docs (k TEXT PRIMARY KEY, data TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings (k TEXT PRIMARY KEY, v TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS issues (id INTEGER PRIMARY KEY AUTOINCREMENT, prop TEXT NOT NULL, room TEXT NOT NULL, date TEXT NOT NULL, type TEXT NOT NULL, text TEXT NOT NULL DEFAULT '', items TEXT NOT NULL DEFAULT '[]', photos TEXT NOT NULL DEFAULT '[]', by TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'open', created_at INTEGER NOT NULL, resolved_at INTEGER, resolved_by TEXT);
CREATE INDEX IF NOT EXISTS issues_status ON issues(status, created_at);
CREATE TABLE IF NOT EXISTS photos (id TEXT PRIMARY KEY, mime TEXT NOT NULL, data TEXT NOT NULL, created_at INTEGER NOT NULL);
-- settings.sync_key：Google 試算表同步金鑰（在 D1 產生，不放進程式碼）
CREATE TABLE IF NOT EXISTS logs (id INTEGER PRIMARY KEY AUTOINCREMENT, prop TEXT NOT NULL, room TEXT NOT NULL, date TEXT NOT NULL, cat TEXT NOT NULL, content TEXT NOT NULL DEFAULT '', by TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT 'web', line_msg TEXT, deleted INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS logs_prop ON logs(prop, deleted, date);
CREATE INDEX IF NOT EXISTS logs_msg ON logs(line_msg);
ALTER TABLE logs ADD COLUMN raw TEXT;
-- 細清：細清項（每 N 個月一次）與每間房的細清回報（照片、細清人員、管理員檢查）
CREATE TABLE IF NOT EXISTS deep_tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, prop TEXT NOT NULL, name TEXT NOT NULL, months INTEGER NOT NULL DEFAULT 1, content TEXT NOT NULL DEFAULT '', standard TEXT NOT NULL DEFAULT '', shots TEXT NOT NULL DEFAULT '[]', deleted INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS deep_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, task_id INTEGER NOT NULL, prop TEXT NOT NULL, room TEXT NOT NULL, date TEXT NOT NULL, by TEXT NOT NULL DEFAULT '', photos TEXT NOT NULL DEFAULT '[]', checks TEXT NOT NULL DEFAULT '[]', note TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'submitted', review_note TEXT NOT NULL DEFAULT '', reviewed_at INTEGER, deleted INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS deep_logs_task ON deep_logs(task_id, deleted, room, date);
